/*---
description: Runtime backreference folding over U+0c0000..U+10ffff under iu, iv and legacy i.
features: [ts-unicode-regexp, ts-unicode-exhaustive, ts-strings, ts-arrays, ts-iteration, ts-numbers]
---*/
// Generated by tooling/unicode-cases/regexp.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Input pairs: Unicode 17.0.0 CaseFolding.txt C/S entries (all others compare with themselves).
// Derived data copyright 2025 Unicode, Inc.; https://www.unicode.org/terms_of_use.html
// Per point hash UTF-16 '0'/'1': iu forward/reverse, iv forward/reverse, i forward/reverse, then neighbor iu/iv/i.
// The neighbor is cp+1, wrapping U+10FFFF to U+0000; input includes every lone surrogate.
// Legacy i consumes UTF-16 units: + captures a whole pair, but comparison still cannot fold supplementary letters.
const foldU = /^([\s\S])\1$/iu, foldV = /^([\s\S])\1$/iv, foldI = /^([\s\S]+)\1$/i;
const froms: number[] = [
];
const targets: number[] = [
];
const expected: number[] = [
  0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5,
  0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5,
  0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5,
  0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5,
  0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5,
  0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5,
  0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5,
  0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5,
  0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5,
  0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5, 0x583f1dc5,
];
assert.sameValue(froms.length, 0);
assert.sameValue(targets.length, 0);
assert.sameValue(expected.length, 80);
let index = 0;
for (let block = 0x0c0000; block < 0x110000; block += 4096) {
  let hash = 2166136261;
  for (let cp = block; cp < block + 4096; cp++) {
    let target = cp;
    if (index < froms.length && froms[index] === cp) target = targets[index++];
    const original = String.fromCodePoint(cp), mapped = String.fromCodePoint(target);
    const forward = original + mapped, reverse = mapped + original;
    const neighbor = original + String.fromCodePoint((cp + 1) % 0x110000);
    hash = Math.imul(hash ^ (foldU.test(forward) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (foldU.test(reverse) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (foldV.test(forward) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (foldV.test(reverse) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (foldI.test(forward) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (foldI.test(reverse) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (foldU.test(neighbor) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (foldV.test(neighbor) ? 0x31 : 0x30), 16777619) >>> 0;
    hash = Math.imul(hash ^ (foldI.test(neighbor) ? 0x31 : 0x30), 16777619) >>> 0;
  }
  assert.sameValue(hash, expected[(block - 0x0c0000) / 4096], "backreference folding block U+" + block.toString(16));
}
assert.sameValue(index, froms.length);
